<?php use App\Core\CSRF; ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">CRM Automotivo</h1><p class="text-secondary mb-0">Retorno por veículo, manutenção e garantia.</p></div><a href="/auto" class="btn btn-outline-secondary">Dashboard</a></div>
<div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-header"><strong>Ações programadas</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Cliente / Veículo</th><th>Tipo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?=date('d/m/Y',strtotime($e['due_at']))?></td><td><?=htmlspecialchars($e['customer_name'])?><br><small><?=htmlspecialchars(trim(($e['make']??'').' '.$e['model'].' '.($e['plate']??'')))?></small></td><td><?=htmlspecialchars(str_replace('_',' ',$e['event_type']))?></td><td><?=htmlspecialchars($e['status'])?></td><td><?php if($e['status']==='pending'):?><form method="post" action="/auto/crm/<?=(int)$e['id']?>/done"><?=CSRF::field()?><button class="btn btn-sm btn-outline-success">Concluir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card"><div class="card-header"><strong>Próximos retornos</strong></div><div class="list-group list-group-flush"><?php foreach($vehicles as $v):?><a class="list-group-item list-group-item-action" href="/vehicles/<?=(int)$v['vehicle_id']?>"><strong><?=htmlspecialchars(trim(($v['make']??'').' '.$v['model']))?></strong><br><small><?=htmlspecialchars($v['customer_name'])?> · <?=htmlspecialchars($v['plate']??'Sem placa')?> · retorno: <?=!empty($v['next_recommended_at'])?date('d/m/Y',strtotime($v['next_recommended_at'])):'não definido'?></small></a><?php endforeach;?></div></div></div></div>
